$('color-reset').onclick=()=>{if(!source)return;textureOrientation='original';$('texture-orientation').value='original';updateTexturePreview();$('tolerance').value='12';$('tolerance-val').textContent='12 / 255';$('detail').checked=true;markPending();refreshColorChecks();toast('Original UVs, colour tolerance 12 and front texture protection restored. Regenerate to apply.');};
$('color-copy').onclick=()=>{
 if(!source||!colorInspection)return;
 const lines=['SmallPart Forge colour diagnostic','Model: '+$('filename').textContent,'Mesh count: '+sourceMeshes.length,'Image texture uses: '+colorInspection.textureCount,'UV orientation: '+textureOrientation,'Color tolerance: '+num('tolerance')+' / 255','Protect front texture details: '+$('detail').checked,'Build: '+(logicalParts.length?`${logicalParts.length} source pieces, ${parts.length} physical SmallParts`:'not generated'),'Which view looks wrong (Original / SmallParts / both): ____________________','','Checks:'];
 for(const check of colorInspection.checks)lines.push(`- ${check.level}: ${check.text}`);
 if(colorDiagnostic?.count)lines.push(`Near-black texture samples: ${colorDiagnostic.nearBlack.map(x=>Math.round(x*100)+'%').join(' / ')} (original / horizontal / vertical / both)`);
 lines.push('','Meshes and materials:');
 for(const row of colorInspection.rows){lines.push(`- ${row.name}: ${row.triangles} triangles; ${row.hidden?'hidden':'visible'}; ${row.outline?'outline shell; ':''}${row.removedReverseFaces} reverse faces repaired`);for(const mat of row.materials)lines.push(`  ${mat.name}: textures ${mat.textures.map(t=>`${t.width}x${t.height} UV${t.channel+1}`).join(', ')||'none'}; tint ${mat.tint.map(n=>n.toFixed(3)).join(',')}; opacity ${mat.opacity}; vertex colors ${mat.vertexColors}`)}
 lines.push('','Please attach the GLB and screenshots of Original and SmallParts from the same angle. This text report contains metadata only; the site does not send files.');
 openExport(lines.join('\n'),'Colour diagnostic report','_colour_report.txt','text/plain','Text only · attach your GLB and screenshots to your developer DM.');
};
const exportBuildJSON=()=>buildJSON(parts,importStats?.stats?.auxiliary?{unplacedAuxiliary:importStats.stats.auxiliary}:null);
$('json').onclick=()=>{if(pendingSettings||!parts.length||parts.length>num('budget'))return;try{openExport(JSON.stringify(exportBuildJSON(),null,2),'Build JSON','_smallparts.json','application/json')}catch(e){toast('Could not create JSON: '+e.message,true)}};
function copyScript(type){if(pendingSettings||!parts.length||parts.length>num('budget'))return;openExport(lua(parts,type),(type==='paint'?'Paint':'Assemble')+' Lua',type==='paint'?'_1_paint.lua':'_2_assemble.lua','text/plain')}
$('paint').onclick=()=>copyScript('paint');$('assemble').onclick=()=>copyScript('assemble');
$('export-select').onclick=()=>{$('script-text').focus();$('script-text').select();$('export-status').textContent='All text selected. Press Ctrl+C (or Cmd+C), then save it using the filename above.'};
$('export-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('script-text').value);$('export-status').textContent='Copied the complete file to your clipboard.'}catch(e){$('script-text').focus();$('script-text').select();const copied=document.execCommand('copy');$('export-status').textContent=copied?'Copied the complete file to your clipboard.':'Clipboard access was blocked. Text is selected; use Copy in your browser or press Ctrl+C / Cmd+C.'}};
$('export-download').onclick=()=>{$('export-status').textContent='Download requested. If no file appears, choose Select all text, copy it, and save it using the filename above.'};
$('script-dialog').addEventListener('close',()=>{const old=exportURL;exportURL=null;if(old)setTimeout(()=>URL.revokeObjectURL(old),30000);$('export-download').removeAttribute('href')});
function prepareBundle(){if(pendingSettings||!parts.length||parts.length>num('budget'))return;const files={'1_paint.lua':lua(parts,'paint'),'2_assemble.lua':lua(parts,'assemble'),'smallparts.json':JSON.stringify(exportBuildJSON(),null,2),'README.txt':`SmallPart Forge\nScale: ${num('build-scale')}% | ${logicalParts.filter(p=>!p.deleted).length} source pieces\n${parts.length} physical SmallParts\n\n1. Place at least ${parts.length} SmallParts on a clean grid in build mode.\n2. Run 1_paint.lua and wait for completion. Include a HalfPlate anchor.\n3. Spawn your aircraft, then run 2_assemble.lua.\n\n${importedBuild?'Script 1 imported preview: this is inferred target geometry, not a recording of post-spawn placement. Original motors and animations cannot be reconstructed from Script 1 alone.'+(importStats?.stats?.auxiliary?` ${importStats.stats.auxiliary} auxiliary blocks have no stored positions and were excluded from the preview and regenerated files.`:''):'Static surface approximation. Animations are not exported.'} Generated Lua follows the referenced converter's pcutils workflow and requires in-game verification.\n`};const blob=zipFiles(files);bundleURL=URL.createObjectURL(blob);$('bundle').href=bundleURL;$('bundle').download=filename.replace(/[^a-z0-9_-]+/gi,'_')+'_'+num('build-scale')+'pct_smallparts.zip';$('bundle').setAttribute('aria-disabled','false')};$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=$('got-it').onclick=()=>$('help-dialog').close();$('help-dialog').onclick=e=>{if(e.target===$('help-dialog'))$('help-dialog').close()};window.__forge={demo,loadFile,loadScript1File};

$('close-script').onclick=()=>$('script-dialog').close();

// Source-piece editor. A logical piece may have several physical SmallPart splits.
let editTool='orbit',snapEdits=false;
function setEditTool(next){editTool=editTool===next?'orbit':next;if(editTool!=='orbit'&&mode==='source'&&partMesh)setMode('parts');for(const [id,tool] of [['box-select','box'],['move-pieces','move'],['rotate-pieces','rotate']]){$(id).classList.toggle('active',editTool===tool);$(id).setAttribute('aria-pressed',String(editTool===tool))}renderer.domElement.style.cursor=editTool==='box'?'crosshair':editTool==='move'||editTool==='rotate'?'grab':''}
function refreshInspector(){
 if(!$('selection-count'))return;
 const ids=[...editor.selection].filter(i=>logicalParts[i]&&!logicalParts[i].deleted),single=ids.length===1;
 $('selection-count').textContent=ids.length?`${fmt(ids.length)} selected`:'Nothing selected';$('delete-pieces').disabled=!ids.length;$('clear-selection').disabled=!ids.length;$('undo-edit').disabled=!editor.history.length;$('redo-edit').disabled=!editor.future.length;$('select-all').disabled=!logicalParts.some(p=>!p.deleted);$('select-piece').disabled=!logicalParts.some(p=>!p.deleted);
 $('box-select').disabled=!parts.length;$('move-pieces').disabled=!ids.length;$('rotate-pieces').disabled=!ids.length;
 if((editTool==='move'||editTool==='rotate')&&!ids.length)setEditTool('orbit');
 $('editor-form').hidden=!ids.length;$('apply-piece').disabled=!single;$('edit-hint').textContent=single?`Source piece #${ids[0]+1} · edits affect all of its SmallPart splits.`:'Select one piece to edit its transform. Appearance and deletion work on multiple pieces.';
 document.querySelectorAll('.transform-input').forEach(el=>el.disabled=!single);
 if(!ids.length)return;
 const p=logicalParts[ids[0]],factor=num('build-scale')/100;
 if(single){for(let j=0;j<3;j++){$('position-'+j).value=+(p.p[j]*factor).toFixed(5);$('size-'+j).value=+(p.s[j]*factor).toFixed(5)}const b=p.basis,m=new THREE.Matrix4().makeBasis(new THREE.Vector3(...b.slice(0,3)),new THREE.Vector3(...b.slice(3,6)),new THREE.Vector3(...b.slice(6,9))),e=new THREE.Euler().setFromRotationMatrix(m,'XYZ');[e.x,e.y,e.z].forEach((x,j)=>$('rotation-'+j).value=+(x*180/Math.PI).toFixed(2))}
 $('piece-color').value='#'+p.c.map(x=>x.toString(16).padStart(2,'0')).join('');$('piece-color-hex').value=$('piece-color').value;$('piece-material').value=p.mat||'s';$('piece-opacity').value=p.mat==='g'?(p.a??.35):1;
}
const editor=new PieceEditor(()=>logicalParts,changed=>{if(changed)applyBuildScale();else{refreshInspector();if(parts.length)drawParts()}});
$('box-select').onclick=()=>setEditTool('box');$('move-pieces').onclick=()=>setEditTool('move');$('rotate-pieces').onclick=()=>setEditTool('rotate');$('snap-toggle').onclick=()=>{snapEdits=!snapEdits;$('snap-toggle').setAttribute('aria-pressed',String(snapEdits));$('snap-toggle').classList.toggle('active',snapEdits)};
$('delete-pieces').onclick=()=>editor.remove();$('undo-edit').onclick=()=>editor.undo();$('redo-edit').onclick=()=>editor.redo();$('clear-selection').onclick=()=>editor.clear();$('select-all').onclick=()=>editor.select(logicalParts.map((p,i)=>p.deleted?-1:i).filter(i=>i>=0));$('select-piece').onclick=()=>{const i=Math.floor(num('piece-number'))-1;if(!logicalParts[i]||logicalParts[i].deleted){toast('That source piece does not exist or was deleted.',true);return}editor.select([i]);if(mode==='source')setMode('parts')};
function appearancePatch(){const hex=$('piece-color-hex').value;if(!/^#[a-f0-9]{6}$/i.test(hex))throw Error('Enter a six-digit hex color, such as #c86432.');return{c:[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)),mat:$('piece-material').value,a:$('piece-material').value==='g'?num('piece-opacity'):1}}
$('piece-color').oninput=()=>$('piece-color-hex').value=$('piece-color').value;$('piece-color-hex').oninput=()=>{if(/^#[a-f0-9]{6}$/i.test($('piece-color-hex').value))$('piece-color').value=$('piece-color-hex').value};
$('piece-material').onchange=()=>{$('piece-opacity').value=$('piece-material').value==='g'?.35:1};
$('apply-appearance').onclick=()=>{try{editor.apply(appearancePatch())}catch(e){toast(e.message,true)}};
$('apply-piece').onclick=()=>{try{const factor=num('build-scale')/100,p=[0,1,2].map(i=>num('position-'+i)/factor),s=[0,1,2].map(i=>num('size-'+i)/factor),e=new THREE.Euler(...[0,1,2].map(i=>num('rotation-'+i)*Math.PI/180),'XYZ'),m=new THREE.Matrix4().makeRotationFromEuler(e),a=m.elements;editor.apply({...appearancePatch(),p,s,basis:[a[0],a[1],a[2],a[4],a[5],a[6],a[8],a[9],a[10]]})}catch(e){toast(e.message,true)}};
$('mesh-search').oninput=()=>{const q=$('mesh-search').value.toLowerCase();document.querySelectorAll('#meshlist label').forEach(el=>el.hidden=!el.dataset.name.includes(q))};
$('zone-add').onclick=()=>{if(!source||zones.length>=3)return;zonePicking=true;setMode('source');$('detail-zones').open=true;updateZoneUI();viewport.scrollIntoView({block:'center',behavior:'smooth'});toast('Click the area on the Original model that needs a different level of detail.')};
$('zone-detail').oninput=()=>{const zone=zones[selectedZone];if(!zone)return;zone.detail=num('zone-detail');$('zone-detail-val').textContent=zone.detail.toFixed(2)+'×';markPending();updateZoneUI()};
for(let i=0;i<3;i++)$('zone-size-'+i).onchange=()=>{const zone=zones[selectedZone];if(!zone)return;const value=num('zone-size-'+i);if(!Number.isFinite(value)||value<.2||value>1000){$('zone-size-'+i).value=zone.size[i];return}zone.size[i]=value;markPending();updateZoneUI()};
$('zone-remove').onclick=()=>{if(selectedZone<0)return;zones.splice(selectedZone,1);selectedZone=Math.min(selectedZone,zones.length-1);markPending();updateZoneUI()};
window.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?editor.redo():editor.undo()}else if(e.key==='Delete'||e.key==='Backspace'){if(editor.selection.size){e.preventDefault();editor.remove()}}else if(e.key==='Escape')editor.clear()});
let pointerStart=null,dragBox=false,moveDrag=null;const raycaster=new THREE.Raycaster();
function previewPoint(event){const r=renderer.domElement.getBoundingClientRect();return{x:event.clientX-r.left,y:event.clientY-r.top,w:r.width,h:r.height}}
function rayOnParts(p){const split=mode==='split',width=split?p.w/2:p.w,offset=split?p.w/2:0;if(split&&p.x<offset)return null;const oldAspect=camera.aspect;camera.aspect=width/p.h;camera.updateProjectionMatrix();camera.updateMatrixWorld(true);raycaster.setFromCamera(new THREE.Vector2((p.x-offset)/width*2-1,1-p.y/p.h*2),camera);const ray=raycaster.ray.clone();camera.aspect=oldAspect;camera.updateProjectionMatrix();return ray}
function restoreMovePreview(){if(!moveDrag)return;for(const item of moveDrag.instances)item.mesh.setMatrixAt(item.index,item.matrix);for(const mesh of new Set(moveDrag.instances.map(item=>item.mesh)))mesh.instanceMatrix.needsUpdate=true;needsRender=true}
renderer.domElement.addEventListener('click',e=>{if(!zonePicking||!source)return;const p=previewPoint(e);scene.updateMatrixWorld(true);camera.updateMatrixWorld(true);raycaster.setFromCamera(new THREE.Vector2(p.x/p.w*2-1,1-p.y/p.h*2),camera);const hit=raycaster.intersectObjects(sourceMeshes.filter(m=>m.visible),false)[0];if(!hit){toast('Click a visible part of the Original model.',true);return}const factor=num('build-scale')/100;zones.push({center:hit.point.toArray().map(n=>+(n/factor).toFixed(3)),size:[2,2,2],detail:1.5});selectedZone=zones.length-1;zonePicking=false;markPending();updateZoneUI();toast('Zone added. Adjust its box and detail multiplier, then Generate.')},true);
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0||mode==='source'||!partMesh)return;const p=previewPoint(e);if(mode==='split'&&p.x<p.w/2)return;pointerStart={...p,shift:e.shiftKey,add:e.ctrlKey||e.metaKey};
 if((editTool==='move'||editTool==='rotate')&&editor.selection.size){const selected=parts.filter(part=>editor.selection.has(part.sourceIndex)),center=new THREE.Vector3();selected.forEach(part=>center.add(new THREE.Vector3(...part.p)));center.divideScalar(selected.length);const plane=new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()),center),ray=rayOnParts(p),start=ray?.intersectPlane(plane,new THREE.Vector3());if(start){const instances=[];partMesh.children.forEach(mesh=>mesh.userData.partIndices.forEach((index,i)=>{if(editor.selection.has(parts[index].sourceIndex)){const matrix=new THREE.Matrix4();mesh.getMatrixAt(i,matrix);instances.push({mesh,index:i,matrix})}}));const axis=new THREE.Vector3($('rotate-axis').value==='x'?1:0,$('rotate-axis').value==='y'?1:0,$('rotate-axis').value==='z'?1:0);moveDrag={kind:editTool,plane,start,center,axis,instances,delta:new THREE.Vector3(),angle:0};controls.enabled=false;renderer.domElement.setPointerCapture(e.pointerId);renderer.domElement.style.cursor='grabbing';return}}
 if(editTool==='box'||e.shiftKey){controls.enabled=false;dragBox=true;renderer.domElement.setPointerCapture(e.pointerId);$('marquee').hidden=false}},true);
renderer.domElement.addEventListener('pointermove',e=>{if(!pointerStart)return;const p=previewPoint(e);if(moveDrag){const snap=snapEdits||e.shiftKey,matrix=new THREE.Matrix4();if(moveDrag.kind==='move'){const hit=rayOnParts(p)?.intersectPlane(moveDrag.plane,new THREE.Vector3());if(!hit)return;moveDrag.delta.copy(hit).sub(moveDrag.start);if(snap)moveDrag.delta.set(...moveDrag.delta.toArray().map(n=>Math.round(n/.1)*.1));for(const item of moveDrag.instances){matrix.copy(item.matrix);matrix.elements[12]+=moveDrag.delta.x;matrix.elements[13]+=moveDrag.delta.y;matrix.elements[14]+=moveDrag.delta.z;item.mesh.setMatrixAt(item.index,matrix)}}else{let angle=(p.x-pointerStart.x)*.6;if(snap)angle=Math.round(angle/5)*5;moveDrag.angle=angle;const center=moveDrag.center,rotation=new THREE.Matrix4().makeTranslation(center.x,center.y,center.z).multiply(new THREE.Matrix4().makeRotationAxis(moveDrag.axis,angle*Math.PI/180)).multiply(new THREE.Matrix4().makeTranslation(-center.x,-center.y,-center.z));for(const item of moveDrag.instances){matrix.copy(item.matrix).premultiply(rotation);item.mesh.setMatrixAt(item.index,matrix)}}for(const mesh of new Set(moveDrag.instances.map(item=>item.mesh)))mesh.instanceMatrix.needsUpdate=true;needsRender=true;return}if(dragBox)Object.assign($('marquee').style,{left:Math.min(p.x,pointerStart.x)+'px',top:Math.min(p.y,pointerStart.y)+'px',width:Math.abs(p.x-pointerStart.x)+'px',height:Math.abs(p.y-pointerStart.y)+'px'})});
renderer.domElement.addEventListener('pointerup',e=>{
 if(!pointerStart)return;const start=pointerStart,p=previewPoint(e),distance=Math.hypot(p.x-start.x,p.y-start.y);pointerStart=null;controls.enabled=true;$('marquee').hidden=true;
 if(moveDrag){const drag=moveDrag,scale=num('build-scale')/100;restoreMovePreview();moveDrag=null;renderer.domElement.style.cursor='grab';if(distance>3){if(drag.kind==='move'&&drag.delta.lengthSq()>1e-9)editor.move(drag.delta.toArray().map(n=>n/scale));if(drag.kind==='rotate'&&Math.abs(drag.angle)>1e-6)editor.rotate(drag.axis.toArray(),drag.angle,drag.center.toArray().map(n=>n/scale))}return}
 const split=mode==='split',width=split?p.w/2:p.w,offset=split?p.w/2:0,oldAspect=camera.aspect;camera.aspect=width/p.h;camera.updateProjectionMatrix();scene.updateMatrixWorld(true);camera.updateMatrixWorld(true);
 if(dragBox&&distance>4){const x0=Math.min(start.x,p.x)-offset,x1=Math.max(start.x,p.x)-offset,y0=Math.min(start.y,p.y),y1=Math.max(start.y,p.y),indices=new Set();for(const part of parts){const v=new THREE.Vector3(...part.p).project(camera),x=(v.x+1)*width/2,y=(1-v.y)*p.h/2;if(v.z>=-1&&v.z<=1&&x>=x0&&x<=x1&&y>=y0&&y<=y1)indices.add(part.sourceIndex)}editor.select(indices,start.add)}else if(distance<5){raycaster.setFromCamera(new THREE.Vector2((p.x-offset)/width*2-1,1-p.y/p.h*2),camera);const hit=raycaster.intersectObjects(partMesh.children.filter(o=>o.visible),false)[0];if(hit){const i=hit.object.userData.partIndices[hit.instanceId];editor.select([parts[i].sourceIndex],false,start.add)}else if(!start.add)editor.clear()}
 dragBox=false;camera.aspect=oldAspect;camera.updateProjectionMatrix();
});
refreshInspector();

renderer.domElement.addEventListener('pointercancel',()=>{restoreMovePreview();moveDrag=null;pointerStart=null;dragBox=false;controls.enabled=true;$('marquee').hidden=true;renderer.domElement.style.cursor=editTool==='box'?'crosshair':editTool==='move'||editTool==='rotate'?'grab':''});

$('vehicle-demo').onclick=()=>{loadObject(createVehicleDemo(),'surface-test-coupe.glb');toast('Curved roof, interior, glass, and emissive headlights — all included in the surface test.')};

$('glass-preview').onclick=()=>{showGlass=!showGlass;$('glass-preview').classList.toggle('active',showGlass);$('glass-preview').setAttribute('aria-pressed',String(showGlass));if(partMesh)partMesh.traverse(o=>{if(o.isMesh)o.visible=showGlass||o.material.opacity>=1});if(source)source.traverse(o=>{if(o.isMesh)for(const m of(Array.isArray(o.material)?o.material:[o.material]))m.visible=showGlass||!m.userData.isGlass})};
